@triton.jit
def min_reduction_kernel(
    x_ptr,
    out_ptr,
    B,
    D1,
    D2,
    stride_xb,
    stride_xd1,
    stride_xd2,
    stride_ob,
    stride_od2,
    BLOCK_D1: tl.constexpr,
    BLOCK_D2: tl.constexpr,
    warp_size: tl.constexpr,
):
    pid_d2 = tl.program_id(0)
    pid_b = tl.program_id(1)

    d2_start = pid_d2 * BLOCK_D2
    d2_offs = d2_start + tl.arange(0, BLOCK_D2)
    d2_mask = d2_offs < D2

    batch_offset = pid_b.to(tl.int64) * stride_xb
    base = x_ptr + batch_offset

    acc = tl.full((BLOCK_D2,), value=float("inf"), dtype=tl.float32)

    for d1_start in range(0, D1, BLOCK_D1):
        d1_offs = d1_start + tl.arange(0, BLOCK_D1)
        mask = (d1_offs[:, None] < D1) & d2_mask[None, :]
        ptrs = base + d1_offs[:, None] * stride_xd1 + d2_offs[None, :] * stride_xd2
        tile = tl.load(ptrs, mask=mask, other=float("inf")).to(tl.float32)
        tile_min = tl.min(tile, axis=0)
        acc = tl.minimum(acc, tile_min)

    out_ptrs = out_ptr + pid_b.to(tl.int64) * stride_ob + d2_offs * stride_od2
    tl.store(out_ptrs, acc.to(tl.float16), mask=d2_mask)


